  'Deze afbeelding naar het AI-model sturen?':
      'Vai nosūtīt šo attēlu MI modelim?',
  'De afbeelding gaat ongewijzigd naar': 'Attēls tiks nosūtīts nemainīts uz',
  'OciDeck lakt niets weg in een afbeelding: gezichten, tekst op een schermafdruk en gegevens in beeld gaan mee.':
      'OciDeck attēlā neko neaizklāj: sejas, teksts ekrānuzņēmumā un redzamie dati tiek nosūtīti līdzi.',
  'De beeldcontrole vond hier een of meer herkenbare gezichten.':
      'Attēlu pārbaude šeit atrada vienu vai vairākas atpazīstamas sejas.',
  'Naast de export komen twee bestanden te staan waarmee een ontvanger de redacties kan natrekken.':
      'Blakus eksportam tiek izveidoti divi faili, ar kuriem saņēmējs var pārbaudīt aizklājumus.',
  'somt op wat er is weggelaten, zonder de waarden zelf. Dit bestand mag met het rapport mee.':
      'uzskaita, kas ir izlaists, bez pašām vērtībām. Šo failu drīkst sūtīt kopā ar ziņojumu.',
  'bevat de sleutels waarmee elke weggelakte waarde is terug te rekenen. Stuur dit bestand niet mee: dan is de redactie ongedaan gemaakt. Bewaar het bij de bron.':
      'satur atslēgas, ar kurām katru aizklāto vērtību var atrēķināt atpakaļ. Nesūtiet šo failu līdzi: tad aizklāšana ir atcelta. Glabājiet to pie avota.',
  'slides': 'slaidi',
  'Achtergehouden': 'Aizturēts',
  'Achtergehouden: strenger geclassificeerd dan de presentatie':
      'Aizturēts: klasificēts stingrāk nekā prezentācija',
  '1 slide achtergehouden door haar TLP': '1 slaids aizturēts tā TLP dēļ',
  'slides achtergehouden door hun TLP': 'slaidi aizturēti to TLP dēļ',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Šie slaidi netiek iekļauti prezentējot, eksportējot vai pakotnē. Paaugstiniet prezentācijas TLP līmeni sadaļā Prezentācijas informācija, lai tos iekļautu.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Visi slaidi ir aizturēti to TLP klasifikācijas dēļ — nav ko rādīt.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Visi slaidi ir aizturēti to TLP klasifikācijas dēļ — nav ko eksportēt.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Visi slaidi ir izlaisti vai aizturēti to TLP klasifikācijas dēļ — nav ko rādīt.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Visi slaidi ir izlaisti vai aizturēti to TLP klasifikācijas dēļ — nav ko eksportēt.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Diagrammu skaitļi netika saglabāti — tie vairs pastāv tikai šajā logā:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Pārlūkā nav atkopšanas pēc avārijas: aizverot šo cilni, nesaglabātais darbs pazūd. Saglabājiet prezentāciju paši.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  Vietējā CVE datubāze (lejupielādi sākat jūs pats): OciDeck iegūst apjoma datus caur api.github.com un laidiena failu, uz kuru šī adrese norāda.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE meklēšana (pēc noklusējuma izslēgta): kad tā ir ieslēgta, jūsu meklējamais vārds nonāk iestatītajā CVE spogulī un, ja tas neko neatrod, ENISA Eiropas datubāzē un MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Iegults YouTube vai Vimeo video ielādē atskaņotāju no attiecīgā pakalpojuma.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Pārlūkā: ja pārlūks atsakās adresi ielādēt tieši, OciDeck mēģina vēlreiz caur serveri, no kura nāca lietotne; tad šī adrese nonāk pie tā servera.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'Atsaukums netika saglabāts. Nākamajā palaišanas reizē jūsu piekrišana atkal būs spēkā.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Sadaļas virsraksts, kas paziņo par jaunu prezentācijas daļu. Turiet to īsu. Pievienojiet fona attēlu no attēlu bibliotēkas.',
  'Bronnen doorzoeken…': 'Meklē avotos…',
  'Niet doorzocht': 'Nav meklēts',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Šī pārbaude nedarbojas tīmekļa versijā: sejas atpazīšanai nepieciešama sistēmas bibliotēka, kuras pārlūkprogrammā nav. Izmantojiet darbvirsmas versiju, lai pārbaudītu sejas attēlos.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'Pilnvarai nepieciešamas lasīšanas un rakstīšanas tiesības krātuvē. Gitea un Forgejo nav meklēšanas serverī; OciDeck meklē lokāli.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'Pilnvarai nepieciešams repo tvērums (vai detalizēti: Contents lasīšanai un rakstīšanai).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'Pilnvarai nepieciešami read_repository, write_repository un read_api. Meklēšanai serverī nepieciešams Advanced vai Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Ātra meklēšana serverī — indeksēšanas aiztures dēļ tikko mainīta kava var iztrūkt.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Multivide netiek saglabāta vienkāršā .md failā',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Attēli, video un audio, ko izvēlējāties šajā cilnē, pastāv tikai atmiņā. Vienkāršs .md fails tos nesaglabā — atverot no jauna, tie būs zuduši. Eksportējiet kā .ocideck pakotni, lai paņemtu multividi līdzi.',
  'Media verwijderd om privacyredenen':
      'Multivide noņemta privātuma apsvērumu dēļ',
