  'bedrijfsnummer (BN)': 'uzņēmuma numurs (BN)',
  'zorgverlenersnummer (NPI)': 'veselības aprūpes sniedzēja numurs (NPI)',
  'Medicare-nummer (MBI) — een zorggegeven':
      'Medicare numurs (MBI) — veselības dati',
  'wacht op verbinding': 'gaida savienojumu',
  'Opgeslagen op deze computer, nog niet in de repository. Gaat mee zodra er weer verbinding is — of nu, met "Wachtrij legen".':
      'Saglabāts šajā datorā, vēl ne repozitorijā. Tiks nosūtīts, tiklīdz atkal būs savienojums — vai tagad, ar "Iztukšot rindu".',
  'Branch (optioneel)': 'Zars (neobligāti)',
  'let op: de standaardbranch is': 'ievērojiet: noklusējuma zars ir',
  'jij werkt op': 'tu strādā uz',
  'werkgeversnummer (EIN)': 'darba devēja numurs (EIN)',
  'laatste vier cijfers van een SSN': 'SSN pēdējie četri cipari',
  'geboortedatum, postcode en geslacht samen — die drie wijzen meestal één persoon aan, ook zonder naam':
      'dzimšanas datums, pasta indekss un dzimums kopā — šie trīs parasti norāda uz vienu personu, arī bez vārda',
  'Het certificaat van deze server wordt niet vertrouwd. Bij een zelf gehoste server kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
      'Šī servera sertifikāts nav uzticams. Pašmitinātā servera to var apskatīt un uzticēties tam sadaļā Iestatījumi → Krātuve.',
  'Het certificaat van de forge wordt niet vertrouwd. Bij een zelf gehoste forge kun je het bekijken en vertrouwen bij Instellingen → Opslag.':
